 "content": "def transform(grid):
    """Recolor the left member of each panel pair when its interior is asymmetric."""
    out = [row[:] for row in grid]
    # The image is arranged as three pairs of 4x4 panels, separated by
    # zero-valued row/column gutters. Use panel-wise, not cell-wise, recoloring.
    for y0 in (1, 6, 11):
        for x0 in (1, 6):
            tile = [[grid[y0 + y][x0 + x] for x in range(4)] for y in range(4)]
            # Measure reflection imbalance of the 4x4 motif.
            h = sum(tile[y][x] != tile[y][3-x] for y in range(4) for x in range(2))
            v = sum(tile[y][x] != tile[3-y][x] for y in range(2) for x in range(4))
            # Preserve symmetric motifs. Asymmetric motifs receive the color
            # associated with their predominant reflection axis.
            if h or v:
                color = 8 if h >= v else 3
                for y in range(4):
                    for x in range(4):
                        if tile[y][x] == 2:
                            out[y0+y][x0+x] = color
    return out
